messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Gait Study — walk / run cycle</title>
<style>
  *{margin:0;box-sizing:border-box}
  html,body{height:100%;overflow:hidden}
  body{background:#ece3d2;color:#4b4237;user-select:none;-webkit-user-select:none;
       font-family:ui-monospace,"Cascadia Mono",Menlo,Consolas,monospace}
  canvas{display:block;cursor:grab;touch-action:none}
  body.dragging canvas{cursor:grabbing}
  .hud{position:fixed;inset:0;pointer-events:none;z-index:2}
  .tl{position:absolute;top:26px;left:30px}
  .eyebrow{font-size:10px;letter-spacing:.22em;opacity:.55}
  h1{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
     font-weight:500;font-size:30px;margin:7px 0 5px;letter-spacing:.01em}
  .sub{font-size:10px;letter-spacing:.16em;opacity:.55}
  .bl{position:absolute;left:30px;bottom:26px;display:flex;align-items:center;gap:14px}
  .mode{font-size:12px;letter-spacing:.22em;color:#a8502b;min-width:58px;transition:opacity .3s}
  .mode.dim{opacity:.4}
  .track{width:170px;height:2px;background:rgba(75,66,55,.22);position:relative;overflow:hidden}
  .track i{position:absolute;inset:0;background:#a8502b;transform-origin:left;transform:scaleX(0)}
  .tc{font-size:10px;opacity:.55;font-variant-numeric:tabular-nums;min-width:46px}
  .br{position:absolute;right:30px;bottom:26px;font-size:10px;letter-spacing:.16em;opacity:.45}
  @media(max-width:640px){h1{font-size:22px}.tl{top:18px;left:20px}.bl{left:20px;bottom:18px}.br{display:none}}
</style>
</head>
<body>
<div class="hud">
  <div class="tl">
    <div class="eyebrow">PROCEDURAL FIGURE — LOW-POLY RIG</div>
    <h1>Gait Study</h1>
    <div class="sub">IDLE 2S · WALK 3S · RUN 3S · IDLE 2S — 10S LOOP</div>
  </div>
  <div class="bl">
    <span class="mode dim" id="mode">IDLE</span>
    <span class="track"><i id="bar"></i></span>
    <span class="tc" id="clock">0.0 s</span>
  </div>
  <div class="br">DRAG ORBIT · WHEEL ZOOM · DOUBLE-CLICK RESET</div>
</div>

<script type="module">
import * as THREE from './three.module.js';

const clamp  = (v,a,b)=>Math.min(b,Math.max(a,v));
const smooth = (a,b,x)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);};

/* ---------------- renderer / scene / camera ---------------- */
const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0xece3d2);
scene.fog = new THREE.Fog(0xece3d2, 9.5, 24);

const camera = new THREE.PerspectiveCamera(37, innerWidth/innerHeight, 0.1, 60);

/* ---------------- lights ---------------- */
scene.add(new THREE.HemisphereLight(0xfff4e2, 0xcfb994, 0.75));
const key = new THREE.DirectionalLight(0xffe8cd, 2.3);
key.position.set(2.6, 5.2, 3.2);
key.castShadow = true;
key.shadow.mapSize.set(2048,2048);
key.shadow.camera.left = key.shadow.camera.bottom = -3.5;
key.shadow.camera.right = key.shadow.camera.top  =  3.5;
key.shadow.camera.near = 0.5; key.shadow.camera.far = 14;
key.shadow.bias = -0.0004; key.shadow.normalBias = 0.03;
scene.add(key);
const rim = new THREE.DirectionalLight(0xe4e8e0, 0.55);
rim.position.set(-3, 2.4, -2.2);
scene.add(rim);

/* ---------------- materials / helpers ---------------- */
const M = {
  wood:  new THREE.MeshStandardMaterial({color:0xc59a63, roughness:0.72, flatShading:true}),
  joint: new THREE.MeshStandardMaterial({color:0x8f6c44, roughness:0.80, flatShading:true}),
  dark:  new THREE.MeshStandardMaterial({color:0x35302a, roughness:0.85, flatShading:true}),
  frame: new THREE.MeshStandardMaterial({color:0x453e35, roughness:0.82, flatShading:true}),
  frameD:new THREE.MeshStandardMaterial({color:0x2c2823, roughness:0.90, flatShading:true}),
  slat:  new THREE.MeshStandardMaterial({color:0x5b5142, roughness:0.95, flatShading:true}),
  roller:new THREE.MeshStandardMaterial({color:0x241f1b, roughness:0.60, flatShading:true}),
  accent:new THREE.MeshStandardMaterial({color:0xb0512d, roughness:0.55, flatShading:true}),
};
const box  = (x,y,z)=>new THREE.BoxGeometry(x,y,z);
const cylG = (rt,rb,h,s=6)=>new THREE.CylinderGeometry(rt,rb,h,s);
const sph  = r=>new THREE.SphereGeometry(r,7,5);
const mk = (geo,mat,x=0,y=0,z=0)=>{
  const m = new THREE.Mesh(geo,mat);
  m.position.set(x,y,z); m.castShadow = m.receiveShadow = true;
  return m;
};

/* ---------------- floor ---------------- */
const floor = new THREE.Mesh(new THREE.PlaneGeometry(70,70),
  new THREE.MeshStandardMaterial({color:0xe0d5bf, roughness:1}));
floor.rotation.x = -Math.PI/2;
floor.receiveShadow = true;
scene.add(floor);

/* ---------------- treadmill ---------------- */
const HX = 1.14, RC = 0.075, YC = 0.10, BELT_TOP = YC + RC + 0.015;   // belt surface 0.19
const tm = new THREE.Group(); scene.add(tm);

tm.add(mk(box(2.12,0.06,0.80), M.frameD, 0, 0.13, 0));                // deck board
tm.add(mk(box(0.60,0.10,0.80), M.frame,  0.75, 0.11, 0));             // motor section
const railGeo = box(2.86,0.17,0.07);
tm.add(mk(railGeo, M.frame, 0, 0.105,  0.435));
tm.add(mk(railGeo, M.frame, 0, 0.105, -0.435));
const capGeo = box(0.12,0.21,0.92);
tm.add(mk(capGeo, M.frameD,  1.38, 0.095, 0));
tm.add(mk(capGeo, M.frameD, -1.38, 0.095, 0));
const skidGeo = box(2.5,0.04,0.09);
tm.add(mk(skidGeo, M.frameD, 0, 0.02,  0.465));
tm.add(mk(skidGeo, M.frameD, 0, 0.02, -0.465));

const rollerGeo = cylG(0.06,0.06,0.80,12); rollerGeo.rotateX(Math.PI/2);
const rollerL = mk(rollerGeo, M.roller,  HX, YC, 0);
const rollerR = mk(rollerGeo, M.roller, -HX, YC, 0);
tm.add(rollerL, rollerR);

/* console column + display */
tm.add(mk(box(0.09,0.98,0.15), M.frame, 1.36, 0.66, 0));
const head = new THREE.Group();
head.position.set(1.36, 1.17, 0); head.rotation.z = 0.35;
tm.add(head);
head.add(mk(box(0.22,0.26,0.58), M.frameD, 0.03, 0, 0));
const barGeo = cylG(0.023,0.023,0.70,8); barGeo.rotateX(Math.PI/2);
tm.add(mk(barGeo, M.frame, 1.22, 1.26, 0));
const gripGeo = cylG(0.035,0.035,0.15,8); gripGeo.rotateX(Math.PI/2);
tm.add(mk(gripGeo, M.accent, 1.22, 1.26,  0.275));
tm.add(mk(gripGeo, M.accent, 1.22, 1.26, -0.275));

const scr = document.createElement('canvas'); scr.width = 256; scr.height = 160;
const sg = scr.getContext('2d');
const scrTex = new THREE.CanvasTexture(scr);
scrTex.colorSpace = THREE.SRGBColorSpace;
scrTex.minFilter = THREE.LinearFilter; scrTex.generateMipmaps = false;
const screen = new THREE.Mesh(new THREE.PlaneGeometry(0.34,0.21),
  new THREE.MeshBasicMaterial({map:scrTex, toneMapped:false}));
screen.position.set(-0.175, 0.02, 0);
screen.rotation.y = -Math.PI/2 + 0.5;
screen.castShadow = false;
head.add(screen);

/* belt slats travelling around the full loop */
const beltLen = 4*HX + 2*Math.PI*RC;
const N_S = 27, spacing = beltLen / N_S;
const slats = new THREE.InstancedMesh(box(0.16,0.03,0.80), M.slat, N_S);
slats.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
slats.receiveShadow = true; slats.castShadow = false; slats.frustumCulled = false;
const cA = new THREE.Color(1,1,1), cB = new THREE.Color(0.82,0.80,0.76);
for (let i=0;i<N_S;i++) slats.setColorAt(i, i%2 ? cB : cA);
slats.instanceColor.needsUpdate = true;
tm.add(slats);

const beltPoint = s => {
  s = ((s % beltLen) + beltLen) % beltLen;
  const top = 2*HX, arc = Math.PI*RC;
  if (s < top) return {x:  HX - s, y: YC+RC, r: 0};                       // top run, moving -x
  s -= top;
  if (s < arc){ const th = Math.PI/2 + s/RC;                              // around back roller
    return {x:-HX + RC*Math.cos(th), y:YC + RC*Math.sin(th), r: th - Math.PI/2}; }
  s -= arc;
  if (s < top) return {x: -HX + s, y: YC-RC, r: Math.PI};                 // return run
  s -= top;
  const th = 1.5*Math.PI + s/RC;                                          // around front roller
  return {x: HX + RC*Math.cos(th), y: YC + RC*Math.sin(th), r: th - Math.PI/2};
};

/* ---------------- low-poly figure (faces +x, side-on to camera) ---------------- */
const figure = new THREE.Group(); figure.position.y = BELT_TOP; scene.add(figure);
const pelvis = new THREE.Group(); pelvis.position.y = 0.895; figure.add(pelvis);
pelvis.add(mk(box(0.23,0.17,0.30), M.dark, 0, 0.02, 0));

const torso = new THREE.Group(); torso.position.y = 0.10; pelvis.add(torso);
const chestGeo = cylG(0.155,0.125,0.42,6); chestGeo.rotateY(Math.PI/6);
const chest = mk(chestGeo, M.wood, 0, 0.25, 0);
chest.scale.x = 0.72;
torso.add(chest);

const headG = new THREE.Group(); headG.position.y = 0.47; torso.add(headG);
headG.add(mk(cylG(0.045,0.05,0.09,6), M.joint, 0, 0.02, 0));
headG.add(mk(box(0.17,0.20,0.165), M.wood, 0.015, 0.155, 0));
headG.add(mk(box(0.035,0.045,0.045), M.wood, 0.105, 0.14, 0));         // nose = facing cue

const buildArm = side => {
  const sh = new THREE.Group(); sh.position.set(0, 0.40, 0.205*side); torso.add(sh);
  sh.add(mk(sph(0.055), M.joint));
  sh.add(mk(cylG(0.047,0.039,0.30), M.wood, 0, -0.15, 0));
  const el = new THREE.Group(); el.position.y = -0.30; sh.add(el);
  el.add(mk(sph(0.042), M.joint));
  el.add(mk(cylG(0.037,0.031,0.26), M.wood, 0, -0.13, 0));
  const hand = mk(box(0.05,0.11,0.06), M.dark, 0.012, -0.31, 0);
  hand.rotation.z = -0.15; el.add(hand);
  return {sh, el, baseY:0.40};
};
const buildLeg = side => {
  const hip = new THREE.Group(); hip.position.set(0, 0, 0.105*side); pelvis.add(hip);
  hip.add(mk(sph(0.06), M.joint));
  hip.add(mk(cylG(0.06,0.048,0.42), M.wood, 0, -0.21, 0));
  const knee = new THREE.Group(); knee.position.y = -0.42; hip.add(knee);
  knee.add(mk(sph(0.05), M.joint));
  knee.add(mk(cylG(0.045,0.034,0.41), M.wood, 0, -0.205, 0));
  const ankle = new THREE.Group(); ankle.position.y = -0.41; knee.add(ankle);
  ankle.add(mk(box(0.23,0.075,0.085), M.dark, 0.045, -0.037, 0));
  return {hip, knee, ankle};
};
const armL = buildArm(1), armR = buildArm(-1);
const legL = buildLeg(1), legR = buildLeg(-1);

/* small floor prop for scale */
const db = new THREE.Group(); db.position.set(-1.78, 0, 0.55); db.rotation.y = 0.55; scene.add(db);
const dbBar = cylG(0.02,0.02,0.36,8); dbBar.rotateZ(Math.PI/2);
db.add(mk(dbBar, M.wood, 0, 0.08, 0));
const plateGeo = cylG(0.08,0.08,0.055,6); plateGeo.rotateZ(Math.PI/2);
db.add(mk(plateGeo, M.dark,  0.125, 0.08, 0));
db.add(mk(plateGeo, M.dark, -0.125, 0.08, 0));

/* ---------------- gait parameters ---------------- */
const CYCLE = 10, FREQ_W = 6.0, FREQ_R = 10.6, BELT_W = 1.45, BELT_R = 4.4;
const WALK = { hip:0.48, kneeBase:0.10, kneeAmp:0.85, stanceKnee:0.05, kneeExp:1.5,
  arm:0.45, elbowBase:0.35, elbowPump:0.35, abduct:0.09, lean:0.09,
  bob:0.016, bobSign:1, sway:0.018, roll:0.05, yaw:0.09,
  plantar:0.30, strike:0.18, dorsi:0.40, ankleK:0.80 };
const RUN = { ...WALK,
  hip:0.96, kneeBase:0.14, kneeAmp:1.85, stanceKnee:0.18, kneeExp:1.3,
  arm:0.85, elbowBase:1.05, elbowPump:0.50, abduct:0.13, lean:0.28,
  bob:0.026, bobSign:-1, sway:0.014, roll:0.09, yaw:0.15,
  plantar:0.55, strike:0.22, dorsi:0.55, ankleK:0.70 };
const IDLE = { ...WALK,
  hip:0, kneeBase:0.05, kneeAmp:0, stanceKnee:0, arm:0, elbowBase:0.16, elbowPump:0,
  abduct:0.07, lean:0, bob:0, sway:0, roll:0, yaw:0, plantar:0, strike:0, dorsi:0 };

/* ---------------- pose solvers ---------------- */
const sq = x => x*x;
function legPose(L, s_, c_, P){
  const h = P.hip * s_;
  const k = P.kneeBase + P.stanceKnee*sq(Math.max(0,-c_))
          + P.kneeAmp*Math.pow(Math.max(0,c_), P.kneeExp);
  L.hip.rotation.z   =  h;
  L.knee.rotation.z  = -k;
  const a = -P.ankleK*(h - k) - P.plantar*sq(Math.max(0,-s_))
          + P.strike*sq(Math.max(0,s_)) + P.dorsi*Math.pow(Math.max(0,c_),1.5);
  L.ankle.rotation.z = clamp(a, -0.85, 1.05);
}
function armPose(A, s_, P, side, t, idleW){
  A.sh.rotation.z = P.arm*s_ + idleW*0.035*Math.sin(t*0.85 + side*1.9);
  A.sh.rotation.x = -side*P.abduct;
  A.el.rotation.z = P.elbowBase + P.elbowPump*Math.pow(Math.max(0,s_),1.3)
                  + idleW*0.02*Math.sin(t*1.1 + side);
}

/* ---------------- console LED readout ---------------- */
let mode = 'IDLE';
function drawScreen(tc, beltV, cad, t){
  sg.fillStyle = '#171208'; sg.fillRect(0,0,256,160);
  sg.textAlign = 'right'; sg.fillStyle = 'rgba(245,165,75,.30)';
  sg.font = '500 15px ui-monospace, Menlo, Consolas, monospace';
  sg.fillText('GAIT-01', 238, 34);
  sg.textAlign = 'left'; sg.fillStyle = '#f5a54b';
  sg.font = '700 46px ui-monospace, Menlo, Consolas, monospace';
  sg.fillText(mode, 18, 66);
  if (t % 1.2 < 0.6){ sg.fillRect(22 + sg.measureText(mode).width, 30, 14, 32); }
  sg.font = '500 24px ui-monospace, Menlo, Consolas, monospace';
  sg.fillText(beltV.toFixed(1) + ' m/s', 18, 102);
  sg.font = '500 16px ui-monospace, Menlo, Consolas, monospace';
  sg.fillText('CAD ' + cad.toFixed(1), 152, 102);
  sg.strokeStyle = 'rgba(245,165,75,.4)'; sg.lineWidth = 2;
  sg.strokeRect(18, 122, 220, 14);
  sg.fillRect(21, 125, 214*(tc/CYCLE), 8);
  sg.fillStyle = 'rgba(0,0,0,.16)';
  for (let y=0; y<160; y+=3) sg.fillRect(0, y, 256, 1);
  scrTex.needsUpdate = true;
}

/* ---------------- HUD ---------------- */
const modeEl  = document.getElementById('mode');
const barEl   = document.getElementById('bar');
const clockEl = document.getElementById('clock');
let lastMode = '';

/* ---------------- orbit (defaults to exact side-on view) ---------------- */
const camTarget = new THREE.Vector3(0.1, 1.0, 0);
const orb  = {th:0, ph:1.42, r:5.2};
const orbT = {th:0, ph:1.42, r:5.2};
let dragging = false, px = 0, py = 0;
const cv = renderer.domElement;
cv.addEventListener('pointerdown', e => {
  dragging = true; px = e.clientX; py = e.clientY;
  cv.setPointerCapture(e.pointerId);
  document.body.classList.add('dragging');
});
cv.addEventListener('pointermove', e => {
  if (!dragging) return;
  orbT.th -= (e.clientX - px) * 0.005;
  orbT.ph  = clamp(orbT.ph - (e.clientY - py) * 0.004, 0.62, 1.53);
  px = e.clientX; py = e.clientY;
});
addEventListener('pointerup', () => { dragging = false; document.body.classList.remove('dragging'); });
cv.addEventListener('wheel', e => {
  e.preventDefault();
  orbT.r = clamp(orbT.r * Math.exp(e.deltaY * 0.001), 3.2, 9.0);
}, {passive:false});
cv.addEventListener('dblclick', () => { orbT.th = 0; orbT.ph = 1.42; orbT.r = 5.2; });

/* ---------------- main loop ---------------- */
const clock = new THREE.Clock();
let simT = 0, phase = 0, beltOff = 0;
const dummy = new THREE.Object3D();

function frame(){
  requestAnimationFrame(frame);
  const dt = Math.min(clock.getDelta(), 0.05);
  simT += dt;
  const tc = simT % CYCLE;

  /* timeline: idle 0-2 · walk 2-5 · run 5-8 · idle 8-10 (smooth crossfades) */
  const wW = smooth(2.0, 2.40, tc) * (1 - smooth(4.7, 5.30, tc));
  const rW = smooth(4.7, 5.30, tc) * (1 - smooth(7.45, 8.15, tc));
  const gW = Math.min(1, wW + rW), idleW = 1 - gW;
  const runMix = (wW + rW) > 1e-4 ? rW / (wW + rW) : 0;
  mode = tc < 2 ? 'IDLE' : tc < 5 ? 'WALK' : tc < 8 ? 'RUN' : 'IDLE';

  /* stride phase + blended gait parameters */
  const freq = FREQ_W + (FREQ_R - FREQ_W) * runMix;
  phase += freq * dt;
  const P = {};
  for (const k in WALK) P[k] = WALK[k] + (RUN[k] - WALK[k]) * runMix;
  for (const k in IDLE) P[k] = IDLE[k] + (P[k] - IDLE[k]) * gW;

  const s = Math.sin(phase), c = Math.cos(phase);
  legPose(legL,  s,  c, P);
  legPose(legR, -s, -c, P);
  armPose(armL, -s, P,  1, simT, idleW);
  armPose(armR,  s, P, -1, simT, idleW);

  const bob = P.bob * P.bobSign * Math.cos(2*phase);
  pelvis.position.y = 0.895 + bob;
  pelvis.position.z = -P.sway*s + idleW*0.012*Math.sin(simT*0.55);
  pelvis.position.x = P.lean * 0.12;
  pelvis.rotation.y = P.yaw * s;
  pelvis.rotation.x = P.roll*c + idleW*0.012*Math.sin(simT*0.42 + 1.3);
  torso.rotation.z  = -P.lean - bob*0.9;
  torso.rotation.y  = -P.yaw * 1.5 * s;
  const br = Math.sin(simT * 1.7);
  chest.scale.y = 1 + 0.02 * br * (0.3 + 0.7*idleW);
  headG.rotation.z = P.lean*0.5 - 0.05;
  headG.rotation.y = idleW*0.16*Math.sin(simT*0.5 + 0.8) - P.yaw*0.3*s;
  headG.rotation.x = idleW*0.03*Math.sin(simT*0.33);
  armL.sh.position.y = armL.baseY + 0.006*br*idleW;
  armR.sh.position.y = armR.baseY + 0.006*br*idleW;

  /* treadmill belt + rollers follow the gait */
  const beltV = BELT_W*wW + BELT_R*rW;
  beltOff += beltV * dt;
  for (let i=0; i<N_S; i++){
    const p = beltPoint(beltOff + i*spacing);
    dummy.position.set(p.x, p.y, 0);
    dummy.rotation.set(0, 0, p.r);
    dummy.updateMatrix();
    slats.setMatrixAt(i, dummy.matrix);
  }
  slats.instanceMatrix.needsUpdate = true;
  const wRoll = beltV / 0.06 * dt;
  rollerL.rotation.z += wRoll;
  rollerR.rotation.z += wRoll;

  /* console + HUD */
  const cad = gW > 0.05 ? freq/Math.PI : 0;
  drawScreen(tc, beltV, cad, simT);
  barEl.style.transform = 'scaleX(' + (tc/CYCLE).toFixed(4) + ')';
  clockEl.textContent = tc.toFixed(1) + ' s';
  if (mode !== lastMode){
    lastMode = mode;
    modeEl.textContent = mode;
    modeEl.classList.toggle('dim', mode === 'IDLE');
  }

  /* damped orbit camera */
  const dk = 1 - Math.exp(-dt*7);
  orb.th += (orbT.th - orb.th)*dk;
  orb.ph += (orbT.ph - orb.ph)*dk;
  orb.r  += (orbT.r  - orb.r )*dk;
  const sp = Math.sin(orb.ph);
  camera.position.set(
    camTarget.x + orb.r*sp*Math.sin(orb.th),
    camTarget.y + orb.r*Math.cos(orb.ph),
    camTarget.z + orb.r*sp*Math.cos(orb.th));
  camera.lookAt(camTarget);

  renderer.render(scene, camera);
}
frame();

addEventListener('resize', () => {
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```
